tool_calls:
awk -F, 'BEGIN{OFS=","}
NR==FNR {
    if (FNR > 1) {
        dept[$1] = $2
    }
    next
}
FNR == 1 {
    print "name,department_name,salary"
    next
}
{
    print $1, dept[$2], $3
}' /data/departments.csv /data/employees.csv > /data/report.csv

cat /data/report.csv

